using WebApiTgBot.Modules.Identity.Models;

namespace WebApiTgBot.Modules.Orders.Models;

/// <summary>
/// Central order entity shared across all sales channels (Website, Telegram, SMM, Admin).
/// Captures customer identity, financial totals, status lifecycle, and order items.
/// </summary>
public class Order
{
    public long Id { get; set; }

    /// <summary>
    /// Unique human-readable and system-wide order reference generated by the backend.
    /// Example: "ORD-20261013-ABC1234".
    /// Enforced globally unique in the database.
    /// </summary>
    public string OrderNumber { get; set; } = string.Empty;

    /// <summary>
    /// Foreign key linking to the centralized ApplicationUser customer identity.
    /// Customers and administrators share the same identity database.
    /// </summary>
    public string CustomerId { get; set; } = string.Empty;

    /// <summary>
    /// Current lifecycle status of the order.
    /// </summary>
    public OrderStatus Status { get; set; } = OrderStatus.PendingPayment;

    /// <summary>
    /// ISO 4217 currency code for the order (default PKR).
    /// </summary>
    public string Currency { get; set; } = "PKR";

    /// <summary>
    /// Subtotal before any discounts or processing adjustments.
    /// Stored with decimal(18,4) precision.
    /// </summary>
    public decimal Subtotal { get; set; }

    /// <summary>
    /// Total amount charged to the customer in the order's currency.
    /// Stored with decimal(18,4) precision.
    /// </summary>
    public decimal TotalAmount { get; set; }

    /// <summary>
    /// The sales channel through which this order originated.
    /// </summary>
    public SalesChannel SalesChannel { get; set; } = SalesChannel.Website;

    /// <summary>
    /// Optional customer notes or fulfillment instructions.
    /// </summary>
    public string? CustomerNotes { get; set; }

    /// <summary>
    /// Client-supplied idempotency key used to prevent duplicate order submissions
    /// from double-clicks, network retries, or lost responses.
    /// Scoped to CustomerId and enforced unique in the database.
    /// </summary>
    public string? IdempotencyKey { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;

    // Navigation properties
    public ApplicationUser Customer { get; set; } = null!;
    public ICollection<OrderItem> Items { get; set; } = new List<OrderItem>();
    public ICollection<OrderStatusHistory> StatusHistory { get; set; } = new List<OrderStatusHistory>();
}
